const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const isReleaseCandidate=window.__ASINA_RELEASE_CANDIDATE__===true;
const publicRoute=isReleaseCandidate?routeForPath(location.pathname):null;
const params=new URLSearchParams(isReleaseCandidate?'':location.search);
if(isReleaseCandidate&&publicRoute){params.set('concept','I-03-C');params.set('draft','1');params.set('view',publicRoute.view);if(publicRoute.page)params.set('page',publicRoute.page)}
const id=params.get('concept');
let data,saved=[],localLabMarker='',imageMetadata={},responsiveImages={},selectedMedia={},siteContent={},isSelectedPreview=false,suppressSectionNumbers=false;try{saved=JSON.parse(localStorage.getItem('asina-lab-selections')||'[]')}catch{}
const dimensions=src=>imageMetadata[src]?`width="${imageMetadata[src].width}" height="${imageMetadata[src].height}" style="--source-width:${imageMetadata[src].width}px"`:"";
const responsiveSizeFor=img=>{const program=img.closest('.program-item');if(img.closest('.home-construction-figure'))return'(max-width: 900px) 90vw, 30vw';if(program)return program.parentElement?.firstElementChild===program?'(max-width: 900px) 90vw, 60vw':'(max-width: 900px) 90vw, 22vw';if(img.closest('.guided-step-images'))return'(max-width: 900px) 24vw, 10vw';if(img.closest('.accessory-item'))return'(max-width: 900px) 45vw, 18vw';return'(max-width: 767px) 100vw, (max-width: 1200px) 50vw, 50vw'};
const image=(src,alt,cls='')=>{const enhanced=guideImageUpscales[src],actualSrc=enhanced?.src||src,responsive=responsiveImages[actualSrc]||responsiveImages[src],defaultSrc=isReleaseCandidate&&responsive?.sources?.length?responsive.sources[0].src:actualSrc,actualDimensions=enhanced?`width="${enhanced.width}" height="${enhanced.height}"`:dimensions(src),srcset=responsive?.sources?.map(item=>`${esc(item.src)} ${item.width}w`).join(', '),responsiveAttrs=srcset?`srcset="${srcset}" sizes="(max-width: 767px) 100vw, (max-width: 1200px) 50vw, 50vw"`:'';return `<img src="${esc(defaultSrc)}" ${responsiveAttrs} alt="${esc(alt)}" class="${cls}" ${actualDimensions} loading="${cls.includes('who-we-are-')?'eager':'lazy'}" decoding="async">`};
function applyResponsiveImages(root=document){root.querySelectorAll('img').forEach(img=>{if(img.hasAttribute('srcset')){img.setAttribute('sizes',responsiveSizeFor(img));return}const raw=img.getAttribute('src');if(!raw||raw.startsWith('data:'))return;let key;try{key=decodeURIComponent(new URL(raw,location.href).pathname.replace(/^\/+/,''))}catch{return}const responsive=responsiveImages[key];if(!responsive)return;if(!img.hasAttribute('width'))img.setAttribute('width',responsive.width);if(!img.hasAttribute('height'))img.setAttribute('height',responsive.height);if(responsive.sources.length<2)return;img.setAttribute('srcset',responsive.sources.map(item=>`${item.src} ${item.width}w`).join(', '));img.setAttribute('sizes',responsiveSizeFor(img))})}
function normalizePublicLinks(root=document){if(!isReleaseCandidate)return;root.querySelectorAll('a[href],img[src],iframe[src],link[href],source[srcset]').forEach(node=>{for(const attr of ['href','src']){const value=node.getAttribute(attr);if(value&&/^assets\//.test(value))node.setAttribute(attr,`/${value}`)}const srcset=node.getAttribute('srcset');if(srcset)node.setAttribute('srcset',srcset.replace(/(^|,\s*)assets\//g,'$1/assets/'));if(node.tagName!=='A')return;const value=node.getAttribute('href')||'';if(!value.startsWith('?'))return;const url=new URL(value,location.href),query=url.searchParams;if(query.get('concept')!=='I-03-C')return;node.setAttribute('href',publicPathForView(query.get('view')||'home',query.get('page')||'',query.get('topic')||'',url.hash))})}
if(isReleaseCandidate)new MutationObserver(records=>records.forEach(record=>record.addedNodes.forEach(node=>{if(node.nodeType===1)normalizePublicLinks(node)}))).observe(document.documentElement,{childList:true,subtree:true});
const homeMotionCSS=`
@media(prefers-reduced-motion:no-preference){
 .i03.ref-c #main-content.home-motion-ready .home-scroll-reveal{opacity:0;transform:translate3d(0,18px,0);transition:opacity 620ms cubic-bezier(.16,1,.3,1),transform 720ms cubic-bezier(.16,1,.3,1);transition-delay:var(--home-reveal-delay,0ms);will-change:opacity,transform}
 .i03.ref-c #main-content.home-motion-ready .home-scroll-reveal.is-visible{opacity:1;transform:none}
 .i03.ref-c #main-content.home-motion-ready .home-scroll-image{clip-path:inset(0 0 0 0);transition:transform 900ms cubic-bezier(.16,1,.3,1),filter 700ms ease;transform:scale(1.015)}
 .i03.ref-c #main-content.home-motion-ready .home-scroll-reveal.is-visible .home-scroll-image{transform:scale(1)}
 .i03.ref-c #main-content.home-motion-ready .guided-step:hover .home-scroll-image,.i03.ref-c #main-content.home-motion-ready .program-item:hover .home-scroll-image,.i03.ref-c #main-content.home-motion-ready .collection-item:hover .home-scroll-image{transform:scale(1.035)}
}
@media(prefers-reduced-motion:reduce){.i03.ref-c #main-content .home-scroll-reveal{opacity:1!important;transform:none!important;transition:none!important}.i03.ref-c #main-content .home-scroll-image{transform:none!important}}
`;
function initHomeScrollMotion(){
 if(!isSelectedPreview||!['127.0.0.1','localhost','[::1]'].includes(location.hostname)||!('IntersectionObserver'in window)||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
 const main=document.querySelector('#main-content');if(!main)return;main.classList.add('home-motion-ready');
 const targets=[...main.querySelectorAll('.section-heading,.program-item,.collection-item,.home-construction-figure,.home-construction-copy,.construction-notes,.guided-step,.quickbook-inline,.decision-sequence-note,.faq-inline-link,.home-process-summary .process-list li,.consultation-layout>*')];
 const groups=new Map();for(const el of targets){const parent=el.parentElement;const index=groups.get(parent)||0;groups.set(parent,index+1);el.classList.add('home-scroll-reveal');el.style.setProperty('--home-reveal-delay',`${Math.min(index,4)*75}ms`)}
 const observer=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target)}},{threshold:.12,rootMargin:'0px 0px -6% 0px'});
 targets.forEach(el=>observer.observe(el));
 main.querySelectorAll('.program-item img,.collection-item img,.guided-step img,.home-construction-figure img').forEach(img=>img.classList.add('home-scroll-image'));
}
const save=(kind,item,index)=>`<button class="save-btn" data-save="${kind}:${index}" aria-pressed="${saved.some(x=>x.key===kind+':'+index)}">${saved.some(x=>x.key===kind+':'+index)?'Saved ✓':'Save for review +'}</button>`;
const section=(key,n,title,lead,content)=>`<section id="${key}" class="section"><div class="section-heading">${n&&!suppressSectionNumbers?`<span class="chapter-index">${n}</span>`:''}<h2>${title}</h2><p class="section-intro">${lead}</p></div><div class="section-content">${content}</div></section>`;
