function program(){return section('program','01','A program for the room.','Cabinetry, countertops and custom furniture packages, supported from design review through coordinated supply.',`<div class="program-grid">${[['Kitchen',data.programImages?.kitchen||data.transformations[0].after_image,'#collections','Three design directions. One considered kitchen.'],['Vanity',data.programImages?.vanity||room(78),'?concept=I-03-C&view=rooms#complete-room','Carry the material story into the bathroom.'],['Wardrobe / Closet',data.programImages?.closet||room(88),'?concept=I-03-C&view=rooms#complete-room','An organized direction for personal spaces.']].map(([name,img,to,copy],i)=>`<a class="program-item" href="${to}">${image(img,name+' application in the Asina Global range')}<div><span class="item-index">0${i+1}</span><h3>${name}</h3><p>${copy}</p><span class="text-link">Explore program ↗</span></div></a>`).join('')}</div>`)}
