function transformContent(i=0){const r=data.transformations[i];if(isSelectedPreview){const m=imageMetadata[r.after_image]||{width:3,height:4};return `<div class="comparison" data-interactive style="--comparison-ratio:${m.width}/${m.height};--split:50%"><img class="after-image" src="${r.after_image}" alt="After: ${esc(r.title)}" ${dimensions(r.after_image)} loading="lazy" decoding="async"><img class="before-image" src="${r.before_image}" alt="Before: ${esc(r.title)}" ${dimensions(r.before_image)} loading="lazy" decoding="async"><span class="comparison-label before-label">Before</span><span class="comparison-label after-label">After</span><div class="comparison-divider"><button type="button" class="comparison-handle" role="slider" aria-label="Reveal before and after photograph" aria-valuemin="0" aria-valuemax="100" aria-valuenow="50" aria-valuetext="50% before, 50% after" aria-orientation="horizontal"><span aria-hidden="true">↔</span></button></div></div><p class="comparison-instruction">Drag the arrow to compare. Use the arrow keys when the handle is focused.</p><div class="comparison-note">Room comparison. Both images fill the same frame; source camera views may differ.</div>`}return `<div class="comparison"><img class="after-image" src="${r.after_image}" alt="After: ${esc(r.title)}" ${dimensions(r.after_image)} loading="lazy" decoding="async"><img class="before-image" src="${r.before_image}" alt="Before: ${esc(r.title)}" ${dimensions(r.before_image)} loading="lazy" decoding="async"><span class="comparison-label before-label">Before</span><span class="comparison-label after-label">After</span><span class="comparison-rule" aria-hidden="true"></span></div><label class="comparison-control">Compare before and after<input type="range" min="0" max="100" value="48" aria-label="Before and after comparison"></label><div class="comparison-note">Room comparison. Views may differ; use the control to reveal each source photograph.</div>`}
