function finishesSection(){const counts=siteContent.catalogFacts?.mainCatalogue?.finish_categories||{};const familyTypes={'Natural Finishes':'Natural wood','Stained':'Stained color','Painted':'Painted color','Matte Lacquer Laminate':'Matte laminate','Acrylic':'Acrylic surface','High Gloss PET':'High-gloss PET','High Pressure Laminate':'High-pressure laminate','Engineered Veneer':'Engineered veneer','Thermally Fused Laminate':'Woodgrain · solid · fabric looks'};const families=Object.entries(materialNames).map(([key,label])=>({key,label,type:familyTypes[key],count:counts[key]??(key==='Thermally Fused Laminate'?58:data.finishes.filter(x=>x.category===key).length)}));return section('finishes','','Explore the finish library','Choose a finish family, then search indexed finishes.',`<div class="finish-library-intro"><p>Nine finish families span natural wood, color, laminate, acrylic and veneer references. Browse the structured local index, then review physical samples and project suitability with our team.</p><p class="finish-record-count"><strong>172</strong><span>indexed finish records in this local explorer</span></p></div><nav class="finish-type-index" aria-label="Choose a finish family">${families.map(f=>`<button type="button" data-material-family="${esc(f.key)}" aria-pressed="false"><span class="family-label">${esc(f.label)}<small class="family-kind">${esc(f.type)}</small></span><small class="family-count">${f.count} refs</small></button>`).join('')}</nav><div class="finish-browser" id="finish-browser"><div class="finish-browser-heading"><div><span class="eyebrow">FINISH LIBRARY</span><h3>Find a colour or surface</h3></div><p>Swatches are visual references. Confirm exact selection and suitability during project review.</p></div><input type="hidden" id="material-filter" value=""><div class="filters"><label>Search by name or code<input type="search" id="finish-search" placeholder="Walnut, White, finish code…"></label><label id="tfl-type-wrap" hidden>TFL look<select id="tfl-type"><option value="">All TFL looks</option><option value="Woodgrain">Woodgrain · 42</option><option value="Solid">Solid · 14</option><option value="Fabric">Fabric · 2</option></select></label></div><div class="finish-tools"><div class="filter-status" id="finish-status" aria-live="polite"></div><button class="outline-btn" id="finish-compare-toggle">Compare finishes (0)</button></div><div id="finish-compare" class="compare-band" hidden></div><div class="finish-grid" id="finish-grid"></div><button class="outline-btn more" id="finish-more">Show more finishes</button></div><p class="fine">Asina Global’s broader finish range includes 600+ colours. This local explorer indexes 172 source finish records. Family names and sample images are references only; they do not establish profile or configuration compatibility. Request quote.</p>`)}
const materialNames={'Natural Finishes':'Natural wood','Stained':'Stained','Painted':'Painted','Matte Lacquer Laminate':'Matte lacquer laminate','Acrylic':'Acrylic','High Gloss PET':'High gloss PET','High Pressure Laminate':'High pressure laminate','Engineered Veneer':'Engineered veneer','Thermally Fused Laminate':'Thermally fused laminate (TFL)'};
function configurations(){return section('configurations','','Cabinet configuration quick reference','Browse cabinet configurations, component codes, and listed options in the Quick Book reader.',`<div class="configuration-quick-reference"><p class="eyebrow">ASINA GLOBAL / QUICK BOOK</p><h3>Configuration codes from the Quick Book.</h3><p>The Quick Book contains 362 cabinet and component references across ten categories. Use it to find names and codes, then send the relevant references with your project plans for review.</p><a class="quickbook-open" href="?concept=I-03-C&view=quickbook"><span><strong>Open the Quick Book Catalogue</strong><small>PDF · Opens in the website reader</small></span><b>Read PDF ↗</b></a><p class="configuration-note">Pricing is quote-only. Dimensions, options, finish compatibility and suitability are confirmed against approved project drawings.</p></div>`)}
function quickBookReader(){const categories=[...new Set(data.products.map(item=>item.category))];return `<section id="quick-book-reader" class="quickbook-reader" aria-label="Quick Book PDF reader"><div class="quickbook-reader-bar"><div><span class="eyebrow">ASINA GLOBAL / QUICK BOOK</span><h2>Cabinet and component reference</h2></div><a class="quickbook-reader-back" href="?concept=I-03-C&view=materials">← Back to Materials</a></div><div class="quickbook-reader-overview"><p><strong>362 configurations across 10 categories.</strong> Search names and codes in the reader, then match shortlisted references to the cabinet layout and design plan.</p><ul aria-label="Quick Book categories">${categories.map(category=>`<li>${esc(category)}</li>`).join('')}</ul><p>Configuration references are starting points. Exact dimensions, options, compatibility and pricing are confirmed against project drawings and approved specifications.</p></div><iframe class="quickbook-pdf" src="assets/reference/quick-book-catalogue.pdf#view=FitH" title="Asina Global Quick Book Catalogue PDF" loading="lazy"></iframe><p class="quickbook-reader-note">Configuration selection follows the project design plan and cabinet layout. Request quote; confirm details during project review.</p></section>`}
function accessoriesCatalogueReader(){return `<section id="accessories-catalogue" class="quickbook-reader" aria-label="Accessories Catalogue PDF reader"><div class="quickbook-reader-bar"><div><span class="eyebrow">ASINA GLOBAL / ACCESSORIES CATALOGUE</span><h2>Accessory reference</h2></div><a class="quickbook-reader-back" href="?concept=I-03-C&view=accessories#range-hood-covers">← Back to Accessories</a></div><iframe class="quickbook-pdf" src="assets/reference/accessories-catalogue.pdf#view=FitH" title="Asina Global Accessories Catalogue PDF" loading="lazy"></iframe><p class="quickbook-reader-note">Use the Accessories Catalogue as a visual reference. Confirm item selection, cabinet fit, hardware details, pricing and suitability during project review.</p></section>`}
function accessories(){const groups=[{id:'corner-storage',title:'Corner storage',note:'Corner-storage references for cabinet layouts.',names:['Lazy Susan','Swing Corner','Wari Corner']},{id:'waste-recycling',title:'Waste & recycling',note:'Waste-bin references for project review.',names:['Waste Bin','Single Garbage Bin','Double Garbage Bin','Top Drawer Double Garbage Bin']},{id:'pullout-storage',title:'Pullout storage',note:'Pullout references for selected cabinet layouts.',names:['Spice Pullout','Basket Pullout']},{id:'pantry-storage',title:'Pantry storage',note:'A swivel-basket reference for pantry layouts.',names:['Pantry Swivel Basket']},{id:'range-hood-covers',title:'Custom range hood covers',note:'Twelve source styles represented by thirteen visual records. Two distinct visuals carry the Hood Range 12 label.',hoods:true}];return section('accessories','','Why pay more for the same function?','Alongside our vendor accessories, we offer Asina Global-branded options that deliver the features you need, at a significantly lower cost.',`<div class="accessory-value-promise"><span class="eyebrow">CABINET ACCESSORIES / A BETTER-VALUE OPTION</span><strong>Same purpose. Better value. Built to perform.</strong><p>Choose storage and waste-management features to complement your cabinet layout, then confirm the specific option during project review.</p></div><nav class="accessory-index" aria-label="Accessory categories">${groups.map((g,i)=>`<a href="#${g.id}"><span>0${i+1}</span>${g.title}<b>↓</b></a>`).join('')}</nav><div class="accessory-categories">${groups.map((g,gi)=>{const entries=g.hoods?data.hoods.map((r,i)=>({r,i,kind:'hoods'})):g.names.map(name=>({r:data.accessories.find(x=>x.name===name),i:data.accessories.findIndex(x=>x.name===name),kind:'accessories'}));return `${g.hoods?accessoriesCatalogueReader():''}<section class="accessory-category${g.hoods?' hood-category':''}" id="${g.id}"><header><div><span class="eyebrow">${g.hoods?'ROOM FEATURE':'FUNCTION'} / ${String(gi+1).padStart(2,'0')}</span><h3>${g.title}</h3></div><p>${g.hoods?'A custom range hood cover adds a polished focal point to your kitchen while enhancing ventilation and airflow. Asina Global designs and builds hood covers to complement your cabinetry—offering tailored style, reliable performance, and factory-direct value.':g.note}</p></header>${g.hoods?`<div class="hood-feature-layout"><div class="hood-feature-copy"><span class="eyebrow">A CLEAR SELECTION PATH</span><ol><li><b>01</b><span>Choose a hood style or share inspiration.</span></li><li><b>02</b><span>Select finish and material to coordinate with the door style.</span></li><li><b>03</b><span>Confirm the size and insert model.</span></li><li><b>04</b><span>Review and approve the shop drawing.</span></li></ol><p>Specific dimensions, insert details, ventilation requirements and suitability are confirmed during project review.</p></div><figure class="hood-feature-image">${image('assets/accessories/hood-cover-kitchen-page-071.jpg','Kitchen with a custom range hood cover, original image extracted from Asina Global reference imagery page 71')}<figcaption>Custom hood cover shown with cabinetry · Original image extracted from Asina Global reference imagery</figcaption></figure></div><p class="hood-enlarge-note">Select a hood image to view it larger.</p><div class="hood-style-index" aria-label="Hood cover style references">${entries.map(({r,i})=>`<article><div class="hood-style-thumb"><button class="hood-image-button" data-detail="hoods:${i}" aria-label="View larger image of ${esc(r.name)}"><span>View larger ↗</span>${image(r.image,r.name+' hood-cover style reference')}</button></div><div class="hood-style-meta"><span>${esc(r.code)}</span><strong>${esc(r.name)}${r.variant===2?' · second visual':''}</strong></div>${save('hoods',r,i)}</article>`).join('')}</div><p class="hood-order-note">12 hood styles are represented by 13 visual records; two visuals carry the Hood Range 12 label.</p>`:`<div class="accessory-grid">${entries.map(({r,i,kind})=>`<article class="accessory-item"><div class="accessory-visual">${image(r.image,r.name+' accessory reference')}</div><div class="accessory-copy"><span class="item-index">AC / ${String(i+1).padStart(2,'0')}</span><h4>${esc(r.name)}</h4><p class="accessory-reference">${esc(r.product_reference||'Accessory reference')}</p><p>${esc(r.description||'Accessory reference.')}</p><div class="accessory-actions"><span>Fit · Confirm during project review</span>${save(kind,r,i)}</div></div></article>`).join('')}</div>`}</section>`}).join('')}</div><p class="accessory-review-note">Accessory and hood references are reviewed against the cabinet design plan. Confirm item selection, cabinet fit, ventilation requirements, hardware details, pricing and suitability during project review.</p>`)}
function faqLibrary(){const groups=siteContent.faqs||{};const faqLinks={"What product selections can I explore with Asina Global?": ["home","Explore product overview"],"How is product selection organized?": ["home#collections","View kitchen directions"],"How many door profiles are shown?": ["profiles","View door profiles"],"How many door profiles can I choose from?": ["profiles","View door profiles"],"How many finish references are shown?": ["materials","View materials and finishes"],"What is the Asina Global TFL finish line?": ["materials","Explore TFL finishes"],"What makes TFL the cost-efficient finish line?": ["materials","Explore TFL finishes"],"Can Asina Global review a custom color or door profile?": ["consultation","Discuss a custom request"],"Which kitchen directions can I explore?": ["home#collections","View kitchen directions"],"Which accessories are shown?": ["accessories","View accessories"],"Does the selection flow include more than kitchens?": ["home#program","View room programs"],"Can a color or profile be customized?": ["consultation","Discuss a custom request"],"How many TFL finishes are shown?": ["materials","Explore TFL finishes"],"How many cabinet configurations are in the Quick Book?": ["quickbook","Open Quick Book references"],"What is the Asina Global Quick Book?": ["quickbook","Open Quick Book references"],"How many products are in the Quick Book?": ["quickbook","Open Quick Book references"],"Can the Quick Book be used as a price list?": ["quickbook","Open Quick Book references"],"Which product categories are included?": ["quickbook","Browse Quick Book categories"],"How does the Quick Book help?": ["quickbook","Open Quick Book references"]};return `<div class="faq-library">${Object.entries(groups).map(([group,items])=>`<section><h3>${esc(group.replace(/([A-Z])/g,' $1').replace(/^./,c=>c.toUpperCase()))}</h3><div class="faq-items">${items.map(([q,a])=>{const link=faqLinks[q];return `<details><summary>${esc(q)}</summary><p>${esc(a)}</p>${link?`<a class="text-link faq-reference-link" href="?concept=I-03-C&view=${link[0]}">${esc(link[1])} ↗</a>`:''}</details>`}).join('')}</div></section>`).join('')}<p class="fine">Answers summarize current product references and project-review practice. Final details are confirmed in the approved project quote.</p></div>`}
function completeRoom(){return section('complete-room','04B','Complete the room.','Bring cabinetry, hood covers, countertops, full-height backsplashes and related room applications into one review.',`<div class="room-grid">${[['Vanity',room(78),'A considered bathroom, from cabinetry to surface.'],['Wardrobe / Closet',room(88),'Carry the material direction into storage.']].map(([name,img,copy],i)=>`<figure>${image(img,name+' application from Asina Global reference imagery')}<figcaption><h3>${name}</h3><p>${copy}</p><button class="text-button" data-room="${name}">Include in project review +</button></figcaption></figure>`).join('')}</div><div class="room-details"><details><summary>Range hood covers · 12 source styles / 13 visual records</summary><div class="hood-grid">${data.hoods.map((r,i)=>`<article>${image(r.image,r.name+' visual '+(i+1))}<h4>${esc(r.name)}</h4>${save('hoods',r,i)}</article>`).join('')}</div><p class="fine">Two visual records share the Hood Range 12 source label. Final form and specifications require review.</p></details><details><summary>Countertop edges · Eight profile visuals</summary><figure class="edge-sheet">${image(data.edges[0].image,'Eight countertop edge-profile examples')}<figcaption>Two source visuals are labeled Roman Ogee. Select the reference visual during project review.</figcaption></figure></details><details><summary>Countertops, backsplashes & furniture packages</summary><p>Quartz, granite, laminate and full-height backsplash directions can be reviewed alongside cabinetry. Custom furniture packages are scoped against project requirements.</p><a href="?concept=I-03-C&view=consultation">Discuss the complete scope ↗</a></details></div>`) }
function faqPage(){return section('faqs','10','Questions, answered.','Explore product references, selection steps, materials, manufacturing-partner roles, and what to prepare for project review.',faqLibrary())}
function consultation(){return section('consultation','11','Bring your project into focus.','Book a design consultation / start a project review.',`<div class="consultation-layout"><div class="consultation-copy"><h3>A clear next step,<br>even with an early idea.</h3><p>Send enough detail to make the first project review useful. A complete drawing set is not required to begin.</p><h4>Project review checklist</h4><ul class="intake-list"><li>Name the program: Kitchen, Vanity, Wardrobe / Closet, or a multi-program scope.</li><li>Share plans, cabinet runs and elevations if available; include an approximate room or unit quantity.</li><li>List preferred door-profile names, finish families or codes, Quick Book references, countertops, edges and accessories.</li><li>Include the project destination, custom requirements and target schedule.</li></ul><p>The local catalog includes 17 door profiles, 172 finish records, 362 cabinet configurations, 10 storage and waste-management accessories, and 8 countertop edge visuals. These are separate references; compatibility is confirmed during project review.</p><h4>What happens during review</h4><p>Asina Global reviews the scope and available drawings, identifies open specification questions, then prepares a quote against the approved project direction. Final compatibility, pricing and schedule are confirmed during that review.</p><p>Asina Global LLC · Longwood, Florida · Project supply for builders, developers, designers, contractors and procurement teams.</p><p class="fine">Your saved choices are discussion candidates.</p><button id="consult-saved" class="outline-btn">Review saved selections (<span data-saved-count>${saved.length}</span>)</button></div><form class="consult-form" id="consult-form" ${isReleaseCandidate?'name="project-review" method="POST" data-netlify="true" netlify-honeypot="bot-field" action="/project-review/received/"':'novalidate'}>${isReleaseCandidate?'<input type="hidden" name="form-name" value="project-review"><input type="hidden" name="selection-summary" value=""><p class="hidden-honeypot"><label>Leave this field blank<input name="bot-field" tabindex="-1" autocomplete="off"></label></p>':''}<p class="local-note">${isReleaseCandidate?'Project review request · Share the essential scope; detailed files can follow after the initial review.':'Local concept preview · Prepare a consultation brief. This form does not send a request or book an appointment.'}</p><label>Your name<input name="name" autocomplete="name" required></label><label>Email<input name="email" type="email" autocomplete="email" required></label><label>Program<select name="program"><option>Kitchen</option><option>Vanity</option><option>Wardrobe / Closet</option><option>Multiple programs / custom furniture</option></select></label><label>Project location & approximate quantity<input name="scope" placeholder="Destination and rooms or units" required></label><label>Project direction<textarea name="notes" rows="4" placeholder="Plans available, style, timing and custom requirements"></textarea></label><p class="fine">${isReleaseCandidate?'Do not send drawings or sensitive files through this form. The team can request project documents after review.':'Keep drawings ready for the eventual consultation. Files are not uploaded in this local preview.'}</p><p class="form-privacy">Project details are used to respond to this request. See the <a href="?concept=I-03-C&amp;view=guide&amp;page=privacy">Privacy Policy</a>.</p><p id="form-error" class="form-error" role="alert"></p><button class="btn" type="submit">${isReleaseCandidate?'Send project review ↗':'Prepare consultation brief ↗'}</button><p id="form-success" role="status"></p></form></div>`)}
function conceptHeader(c,draftMode=false){const root=`?concept=${c.id}`;const labMarking=draftMode?'':`<div class="lab-strip"><a href="${c.stage===2?'?stage=2':'?stage=1'}">← ${c.stage===2?'I-03 refinements':'All ten concepts'}</a><span>${c.id} · ${c.id[0]==='I'?'Impeccable':'Design Taste'} · ${c.id==='I-03-C'?'Selected local preview':c.stage===2?'Stage 2 refinement':'Local exploration'}</span><a href="?notes=${c.id}">Design dossier ↗</a></div>`;return `${labMarking}<header class="site-header"><a class="brand" href="${root}" aria-label="Asina Global home">${image(data.logo,'Asina Global')}</a><button class="menu-toggle" aria-expanded="false" aria-controls="site-nav">Menu +</button><nav class="site-nav" id="site-nav" aria-label="Main"><a href="${root}&view=profiles">Door profiles</a><a href="${root}&view=technical">Cabinet specs</a><a href="${root}&view=materials">Materials</a><a href="${root}&view=countertops">Countertops</a><a href="${root}&view=rooms">Complete room</a><a href="${root}&view=guides">Project guides</a><button id="saved-open" class="saved-button">Saved <span data-saved-count>${saved.length}</span></button><a href="${root}&view=consultation" class="nav-cta">Start a project ↗</a></nav></header>`}
function chapterNav(view){const activeView=view==='guide'?'guides':view==='accessories-catalogue'?'accessories':view;const links=[['home','Overview'],['rooms','Same space. Bigger impact.'],['technical','Cabinet specs'],['profiles','Door profiles'],['materials','Materials & finishes'],['quickbook','Quick Book PDF'],['accessories','Accessories'],['countertops','Countertops'],['faqs','FAQs'],['guides','Project guides'],['about','Who We Are'],['consultation','Consultation']];return `<nav class="chapter-nav" aria-label="Product sections">${links.map(([key,label])=>`<a href="?concept=I-03-C&view=${key}" ${key===activeView?'aria-current=page':''}>${label}</a>`).join('')}</nav>`}

function materialLayoutPicker(active){const variants=[['1','Material Atelier','Finish families first'],['2','Comparison Ledger','Tables first'],['3','Specimen Index','Catalog scanning'],['4','Price Compass','Relative tiers first'],['5','Surface Library','Swatch-led']];return `<nav class="material-layout-picker" aria-label="Material page layout previews"><span>LAYOUT PREVIEWS</span>${variants.map(([id,name,desc])=>`<a href="?concept=I-03-C&view=materials&layout=${id}${id==='4'?'&price=1':''}" ${active===id?'aria-current="page"':''}><strong>${name}</strong><small>${desc}</small></a>`).join('')}</nav>`}
function priceVariantPicker(active){const variants=[['1','Tier strip','One-line relative scale'],['2','Material steps','Grouped by tier'],['3','Value bands','Large price hierarchy'],['4','Cost & character','Price beside finish traits'],['5','Spec ledger','Dense comparison view']];return `<nav class="price-variant-picker" aria-label="Price Compass layout previews"><span>PRICE COMPASS / LAYOUTS</span>${variants.map(([id,name,desc])=>`<a href="?concept=I-03-C&view=materials&layout=4&price=${id}" ${active===id?'aria-current="page"':''}><strong>${name}</strong><small>${desc}</small></a>`).join('')}</nav>`}
function materialPage(layout,priceVariant){const comparisonFirst=layout==='2'||layout==='4';return `<div class="materials-page materials-layout-${layout}${layout==='4'?' price-variant-'+priceVariant:''}">${comparisonFirst?`${materialComparisonSection()}${finishesSection()}`:`${finishesSection()}${materialComparisonSection()}`}</div>`}
function catalogPageHeader(view){if(view==='home')return '';const pages={lookbook:['Same space. Bigger impact.','Popular kitchen pairings, four before-and-after transformations, hardware references, and complete-room applications, brought together.'],technical:['Cabinet Box Specifications','Construction details from the cabinet box through the door and drawer front.'],profiles:['Door Profiles','Compare the 17 indexed door-profile references.'],materials:['Materials & Finishes','600+ colours, 9 materials, endless possibilities. Fully custom finishes crafted for quality, durability, and timeless style.'],configurations:['Cabinet Configuration Quick Reference','Open the Quick Book reader for cabinet configurations, names, codes, and listed options.'],quickbook:['Quick Book Catalogue','Browse cabinet and component references inside the site.'],accessories:['Cabinet accessories & custom hood covers','Compare Asina Global-branded accessory options, vendor references and 12 custom range hood styles (13 visuals). Review cabinet fit and project requirements with the team.'],'accessories-catalogue':['Accessories Catalogue','Browse the Asina Global Accessories Catalogue in the on-page reader.'],countertops:['Countertops & Full-Height Backsplashes','Asina Global countertops and full-height backsplashes bring refined style and lasting performance to every space.'],rooms:['Same space. Bigger impact.','Popular kitchen pairings, four before-and-after transformations, hardware references, and complete-room applications, brought together.'],faqs:['Project FAQs','Answers from the Asina Global content brief, grouped by topic.'],consultation:['Start a Project Review','Share the room, selections, project scope, and destination for consultation.']};const [title,summary]=pages[view]||pages.rooms;return `<div class="catalog-page-header"><a href="?concept=I-03-C&view=home">← Product journey</a><p class="eyebrow">ASINA GLOBAL / PRODUCT JOURNEY</p><h1>${title}</h1><p>${summary}</p></div>`}
function homeConstruction(){
 const callouts=[['A','3/4-inch Hard Rock Maple melamine'],['B','Additional adjustment for drawer fronts and box, with matching edge tape'],['C','Full-height adjustable shelves'],['D','Six-way adjustable, full-extension soft-close hinges listed as standard'],['E','Commercial-grade adjustable legs'],['F','Soft-close undermount slides listed as standard'],['G','3/4-inch solid back'],['H','Heavy-duty Confirmat screws and wooden dowels']];
 return section('construction-overview','05','Construction, at a glance.','A concise introduction to the cabinet build and front choices. Open the technical view for the labeled breakdown and material details.',`<div class="home-construction-layout"><figure class="home-construction-figure">${image('assets/catalog-detail/cabinet-box-breakdown-xref486.png','Cabinet construction diagram with lettered component callouts A through H')}<figcaption>Cabinet component references</figcaption></figure><div class="home-construction-copy"><span class="eyebrow">Cabinet box / Construction reference</span><h3>Start with the build, then choose the face.</h3><ol class="construction-key" aria-label="Cabinet diagram callouts A through H">${callouts.map(([letter,copy])=>`<li><span>${letter}</span><p>${copy}</p></li>`).join('')}</ol><dl class="home-front-box-options"><div><dt>Cabinet box options</dt><dd>Particleboard · HDF · Plywood</dd></div><div><dt>Door and drawer-front options</dt><dd>Stained · HDF · Engineering Veneer · HPL · High-Gloss Acrylics · TFL</dd></div></dl><p class="fine">Front choices are listed separately from the cabinet box. Confirm exact build-up and suitability during project review.</p><a class="text-link" href="?concept=I-03-C&view=technical">See detailed construction and material specs ↗</a></div></div><details class="construction-notes" open><summary>Construction, finish and installation notes</summary><div class="construction-notes-grid"><section><h4>Built to stay square for years</h4><ul><li>Commercial-grade materials and hardware come standard.</li><li>Thicker panels, stronger joints, smoother function.</li></ul></section><section><h4>Stronger box</h4><ul><li>Stays square: reinforced with Confirmat screws and dowels.</li><li>Resists warping: thick panels and solid back support.</li></ul></section><section><h4>Cleaner finish</h4><ul><li>Tighter reveals: precise panel alignment for consistent gaps.</li><li>Finished interiors are described as cleaner looking and longer lasting.</li></ul></section><section><h4>Easier install</h4><ul><li>The 3/4-inch back lets uppers mount directly to the wall; no rails required.</li><li>Commercial adjustable legs support faster leveling.</li><li>Front and box adjustments support a dialed-in fit.</li></ul></section></div><p class="fine">These construction references summarize the current specification. Confirm project-specific details in the approved project documents.</p></details>`)
}
function homeDecisionSequence(){
 const cards=[
  {view:'profiles',title:'Door profile',copy:'Compare the lines and details of the indexed door profiles.',count:`${data.profiles.length} profiles`,images:data.profiles.slice(0,3).map(x=>[x.image,x.name+' door profile'])},
  {view:'materials',title:'Material & finish',copy:'Explore finish families and surface character.',count:`${data.finishes.length} records · 9 families`,images:data.finishes.slice(0,3).map(x=>[x.image,x.name+' finish sample'])},
  {view:'accessories',title:'Accessories',copy:'Bring storage and waste-management needs into the review.',count:`${data.accessories.length} accessory references`,images:data.accessories.slice(0,3).map(x=>[x.image,x.name+' accessory'])},
  {view:'countertops',title:'Countertops & backsplashes',copy:'Browse 79 quartz slab references, review granite by project, then choose an edge and backsplash direction.',count:'79 quartz references · 8 edge visuals',images:[[data.transformations.find(x=>x.program==='Kitchen'&&x.story_tags?.includes('backsplash'))?.after_image||data.transformations[0].after_image,'Kitchen countertop and backsplash direction']]},
  {view:'rooms',title:'Complete room',copy:'Bring kitchen pairings, transformations, vanity, wardrobe and surfaces together.',count:'Look Book · transformations · room applications',images:[[data.collectionImages?.[1]||data.transformations[1].after_image,'Complete room inspiration']]}
 ];
 return section('decision-sequence','','A guided specification sequence.','Move from door profile through finish, accessories, countertops and the complete room. Use the Quick Book as a separate cabinet-code reference.',`<div class="guided-sequence">${cards.map(c=>`<a class="guided-step" href="?concept=I-03-C&view=${c.view}"><div class="guided-step-images ${c.images.length===1?'single':''}">${c.images.map(([src,alt])=>image(src,alt)).join('')}</div><div class="guided-step-copy"><h3>${c.title}</h3><p>${c.copy}</p><span class="guided-step-count">${c.count}</span><span class="text-link">Open ${c.title.toLowerCase()} references ↗</span></div></a>`).join('')}</div><a class="quickbook-inline" href="?concept=I-03-C&view=quickbook">Cabinet configuration quick reference · Open the Quick Book PDF ↗</a><p class="decision-sequence-note">Selections are independent references; exact substrate, finish build-up, sizing and suitability are confirmed during project review.</p><a class="faq-inline-link" href="?concept=I-03-C&view=faqs">Questions about the process? Browse project FAQs ↗</a>`)
}
function quickBookReference(){return `<aside class="configuration-reference-bar" aria-label="Cabinet configuration reference"><div><span class="eyebrow">QUICK BOOK / CABINET REFERENCE</span><h3>Configuration follows the cabinet layout.</h3><p>The Quick Book includes many cabinet and component configurations. The selection is based on the project design plan and cabinet layouts, then confirmed during project review.</p></div><a href="?concept=I-03-C&view=quickbook"><span><strong>Quick Book PDF</strong><small>362 references · 10 categories</small></span><b>Open reference ↗</b></a></aside>`}
function nextStage(view){const next={technical:['profiles','Door profiles','Compare the indexed door profiles and select a direction.'],profiles:['materials','Materials & finishes','Explore finish families and compare surface references.'],materials:['accessories','Accessories','Bring storage and waste-management needs into the project review.'],configurations:['accessories','Accessories','Add storage and waste-management needs to the review.'],quickbook:['accessories','Accessories','Continue from cabinet references to storage and waste-management options.'],accessories:['countertops','Countertops & backsplashes','Choose quartz, granite or laminate, then review the edge and backsplash direction.'],countertops:['rooms','Complete room','Bring the surface direction into the full room review.'],rooms:['consultation','Start a project review','Bring the room direction and saved choices into a consultation.'],lookbook:['technical','Cabinet specs','Move from room inspiration to construction details.'],faqs:['consultation','Start a project review','Share the questions and project details with Asina Global.']};const item=next[view];if(!item)return '';const [to,title,copy]=item;return `<nav class="next-stage" aria-label="Continue to the next step"><span class="eyebrow">Continue the decision path</span><a href="?concept=I-03-C&view=${to}"><span><strong>${title}</strong><small>${copy}</small></span><b>Next step ↗</b></a></nav>`}
let finishPageSize=12,productPageSize=8,finishLimit=12,productLimit=8;
function renderFinishes(){const family=document.querySelector('#material-filter').value,q=document.querySelector('#finish-search').value.toLowerCase(),type=document.querySelector('#tfl-type').value;const istfl=family==='Thermally Fused Laminate';document.querySelector('#tfl-type-wrap').hidden=!istfl;const source=istfl?data.tfl:data.finishes;const list=source.filter(x=>(!family||istfl||x.category===family)&&(!istfl||!type||x.category===type)&&(x.name+' '+(x.code||'')).toLowerCase().includes(q));document.querySelector('#finish-status').textContent=`${list.length} ${istfl?'TFL ':''}finish records${q?' matching your search':''}`;document.querySelectorAll('[data-material-family]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.materialFamily===family)));document.querySelectorAll('[data-material-family]').forEach(b=>b.classList.toggle('is-active',b.dataset.materialFamily===family));document.querySelector('#finish-grid').innerHTML=list.slice(0,finishLimit).map(r=>{const kind=data.tfl.includes(r)?'tfl':'finishes',i=data[kind].indexOf(r);return `<article class="finish-item"><button class="image-button" data-detail="${kind}:${i}" aria-label="View ${esc(itemTitle(r))}">${image(r.image,r.name+' material swatch')}</button><div><span class="spec-code">${esc(r.code||(r.category==='Natural Finishes'?'Natural wood':'Code not listed'))}</span><h3>${esc(r.name)}</h3><p>${esc(materialNames[r.category]||r.category)}</p><label class="compare-check"><input type="checkbox" data-compare-finish="${kind}:${i}" ${comparedFinishes.has(kind+':'+i)?'checked':''}> Compare finish</label>${save(kind,r,i)}</div></article>`}).join('')||'<p class="empty-state">No finishes match. Clear your search or choose another material family.</p>';document.querySelector('#finish-more').hidden=list.length<=finishLimit}
function renderProducts(){const cat=document.querySelector('#product-category').value,q=document.querySelector('#product-search').value.toLowerCase();const source=data.products.filter(x=>(!cat||x.category===cat)&&(x.name+' '+x.code).toLowerCase().includes(q));const seen=new Set();const list=source.filter(r=>{if(!isSelectedPreview)return true;const key=[r.code,r.name,r.category].join('|');if(seen.has(key))return false;seen.add(key);return true});const shown=list.slice(0,productLimit);document.querySelector('#product-status').textContent=cat?`${list.length} code entries · ${source.length} source records in ${cat}`:`${list.length} code entries · ${source.length} Quick Book records across 10 categories`;document.querySelectorAll('[data-product-family]').forEach(b=>{const active=b.dataset.productFamily===cat;b.setAttribute('aria-pressed',String(active));b.classList.toggle('is-active',active)});document.querySelector('#product-grid').innerHTML=shown.map(r=>{const i=data.products.indexOf(r);return `<tr><td data-label="Code"><span class="spec-code">${esc(r.code)}</span></td><td data-label="Configuration"><div class="configuration-reference"><button class="configuration-thumb" data-detail="products:${i}" aria-label="View ${esc(r.name)} reference image">${image(r.image,r.name+' Quick Book configuration reference')}</button><div><strong>${esc(r.name)}</strong>${r.sharedSourceVisual?`<small class="source-visual-note">${r.duplicateSourceIndices?'Repeated source records are grouped under this code.':'The source reuses this exterior image; review the configuration details with the project drawings.'}</small>`:''}</div></div></td><td data-label="Category">${esc(r.category)}</td><td data-label="Project review"><div class="configuration-actions"><button class="text-button" data-detail="products:${i}">Review ↗</button>${save('products',r,i)}</div></td></tr>`}).join('')||'<tr><td colspan="4" class="empty-state">No configurations match. Clear the search or choose another category.</td></tr>';document.querySelector('#product-more').hidden=list.length<=productLimit}
function toast(text){const t=document.querySelector('.toast');t.textContent=text;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),3200)}
function persist(){localStorage.setItem('asina-lab-selections',JSON.stringify(saved));document.querySelectorAll('[data-saved-count]').forEach(e=>e.textContent=saved.length);document.querySelectorAll('[data-save]').forEach(b=>{const on=saved.some(x=>x.key===b.dataset.save);b.setAttribute('aria-pressed',on);b.textContent=on?'Saved ✓':'Save for review +'});if(!document.querySelector('#saved-panel').hidden)renderSaved()}
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function renderSaved(){const p=document.querySelector('#saved-panel');p.innerHTML=`<div class="panel-head"><h2 id="saved-title">Saved for consultation</h2><button data-close-saved aria-label="Close saved selections">Close ×</button></div><p>Independent review candidates. Final suitability is confirmed during project review.</p>${saved.length?`<ul class="saved-list">${saved.map(x=>`<li><div><small>${esc(x.kind)}</small><h3>${esc(x.name)}</h3><p>${esc(x.code||'Product reference')}</p></div><button data-remove="${esc(x.key)}" aria-label="Remove ${esc(x.name)}">Remove ×</button></li>`).join('')}</ul><button class="btn" id="export-selections">Download selection brief ↗</button>`:'<div class="empty-state">Your selection brief is empty. Browse a profile, finish or configuration and choose “Save for review”.</div>'}<a class="outline-btn" href="?concept=I-03-C&view=consultation" data-close-saved>Continue to consultation ↗</a>`}
function renderCompare(){const band=document.querySelector('#profile-compare');band.innerHTML=compared.size?`<p>Compare silhouettes. These are independent profile references, not a compatibility assessment.</p><div class="profile-comparison">${[...compared].map(i=>`<figure>${image(data.profiles[i].image,data.profiles[i].name)}<figcaption>${esc(data.profiles[i].name)}</figcaption></figure>`).join('')}</div>`:'<p>Select up to three profiles using the compare checkboxes.</p>';document.querySelector('#compare-toggle').textContent=`Compare profiles (${compared.size})`}
function renderFinishCompare(){const band=document.querySelector('#finish-compare');band.innerHTML=comparedFinishes.size?`<p>Compare material references. Screen swatches are indicative; physical samples confirm finish and suitability.</p><div class="finish-comparison">${[...comparedFinishes].map(([key,r])=>`<figure>${image(r.image,r.name)}<figcaption><strong>${esc(r.name)}</strong><br>${esc(r.code||(r.category==='Natural Finishes'?'Natural wood':'Code not listed'))}<br>${esc(materialNames[r.category]||r.category)}<br><button class="text-button" data-uncompare-finish="${key}">Remove ×</button></figcaption></figure>`).join('')}</div>`:'<p>Select up to four finish references using the compare checkboxes.</p>';document.querySelector('#finish-compare-toggle').textContent=`Compare finishes (${comparedFinishes.size})`;document.querySelectorAll('[data-compare-finish]').forEach(b=>b.checked=comparedFinishes.has(b.dataset.compareFinish));}
function changeStory(i){document.querySelector('#comparison-host').innerHTML=transformContent(i);applyResponsiveImages(document.querySelector('#comparison-host'));document.querySelector('#story-copy').innerHTML=storyCopy(i);document.querySelectorAll('[data-story]').forEach(b=>b.setAttribute('aria-pressed',Number(b.dataset.story)===i));}
function showDetail(key){const[kind,num]=key.split(':'),r=data[kind][Number(num)];const dialog=document.querySelector('#detail-drawer');dialog.innerHTML=`<button class="close-detail" aria-label="Close details">Close ×</button>${image(r.image,r.name,kind==='hoods'?'hood-detail-image':'')}<span class="eyebrow">${esc(r.category||kind)}</span><h2>${esc(r.name)}</h2>${r.code?`<p class="spec-code">${esc(r.code)}</p>`:''}<p>${kind==='products'?'Quick Book configuration reference. Final dimensions, interior options, finished ends and any custom changes are confirmed against your project drawings.':kind==='hoods'?'Hood-cover visual reference. Confirm the selected style, finish and material, dimensions, insert model, and shop drawing during project review.':'Material finish reference. Screen imagery is indicative; physical sample approval confirms the final direction.'}</p><dl><dt>Pricing</dt><dd>Request quote</dd><dt>Suitability</dt><dd>Confirm during project review</dd></dl>${r.technicalImage?`<figure class="technical-reference">${image(r.technicalImage,r.name+' source interior reference')}<figcaption>Source interior reference · Confirm final specifications during project review</figcaption></figure>`:''}${save(kind,r,Number(num))}<a href="?concept=I-03-C&view=consultation" class="btn" data-close-detail>Discuss this direction ↗</a>`;applyResponsiveImages(dialog);dialog.showModal()}
function initSelectedPageInteractions(view){
 const menu=document.querySelector('.menu-toggle');if(menu)menu.onclick=e=>{const open=e.currentTarget.getAttribute('aria-expanded')==='true';e.currentTarget.setAttribute('aria-expanded',String(!open));document.querySelector('.site-nav').classList.toggle('open',!open)};
 document.querySelector('.site-nav')?.addEventListener('click',e=>{if(e.target.closest('a')){document.querySelector('.site-nav').classList.remove('open');menu?.setAttribute('aria-expanded','false')}});
 if(view==='countertops'){
  const dialog=document.querySelector('#detail-drawer');
  dialog.addEventListener('close',()=>dialog.classList.remove('countertop-image-detail'));
  dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});
  const catalog=document.querySelector('#countertop-surface-grid');
  const filterCatalog=()=>{
   const collection=document.querySelector('#countertop-collection')?.value||'All';
   const query=document.querySelector('#countertop-search')?.value.trim().toLowerCase()||'';
   let count=0;
   catalog?.querySelectorAll('.countertop-catalog-item').forEach(item=>{const visible=(collection==='All'||item.dataset.surfaceCollection===collection)&&(!query||item.dataset.surfaceSearch.includes(query));item.hidden=!visible;if(visible)count++});
   const label=document.querySelector('#countertop-result-count');if(label)label.textContent=`${count} quartz surface reference${count===1?'':'s'}${collection==='All'?'':` · ${collection}`}`;
   const empty=document.querySelector('#countertop-no-results');if(empty)empty.hidden=count>0;
  };
  document.querySelector('#countertop-collection')?.addEventListener('change',filterCatalog);
  document.querySelector('#countertop-search')?.addEventListener('input',filterCatalog);
  document.addEventListener('click',e=>{
   const material=e.target.closest('[data-surface-material]');
   if(material){const selected=material.dataset.surfaceMaterial;document.querySelectorAll('[data-surface-material]').forEach(button=>{const active=button===material;button.classList.toggle('is-active',active);button.setAttribute('aria-pressed',String(active))});document.querySelectorAll('[data-surface-panel]').forEach(panel=>panel.hidden=panel.dataset.surfacePanel!==selected);return}
   const trigger=e.target.closest('[data-countertop-image]');if(!trigger)return;
   const code=trigger.dataset.countertopCode,src=trigger.dataset.countertopImage,isEdge=trigger.dataset.countertopKind==='edge';
   dialog.classList.add('countertop-image-detail');
   dialog.innerHTML=`<button class="close-detail" aria-label="Close ${isEdge?'edge profile':'surface sample'} detail">Close ×</button><figure><img class="${isEdge?'countertop-edge-detail-image':''}" src="${esc(src)}" alt="${esc(code)} ${isEdge?'edge profile':'countertop surface'} shown enlarged"><figcaption>${esc(code)} · ${isEdge?'Edge profile reference':'Surface sample reference'}</figcaption></figure><p>${isEdge?'Edge profile imagery is a visual reference. Confirm the selected edge treatment during project review.':'Sample imagery is a visual reference. Confirm the selected surface and project suitability during project review.'}</p>`;
   applyResponsiveImages(dialog);dialog.showModal()
  });
 }
 if(view==='materials'){renderFinishes();for(const sel of ['#material-filter','#finish-search','#tfl-type'])document.querySelector(sel)?.addEventListener(sel.includes('search')?'input':'change',()=>{finishLimit=finishPageSize;renderFinishes()});document.querySelectorAll('[data-material-family]').forEach(b=>b.addEventListener('click',()=>{document.querySelector('#material-filter').value=b.dataset.materialFamily;finishLimit=finishPageSize;renderFinishes();document.querySelector('#finish-browser').scrollIntoView({behavior:'smooth',block:'start'})}));document.querySelector('#finish-compare-toggle').onclick=()=>{const el=document.querySelector('#finish-compare');el.hidden=!el.hidden};document.querySelector('#finish-more').onclick=()=>{finishLimit+=24;renderFinishes()}}

 if(view==='profiles'){renderCompare();document.querySelector('#profile-search')?.addEventListener('input',e=>{const list=data.profiles.filter(r=>r.name.toLowerCase().includes(e.target.value.toLowerCase()));document.querySelector('#profile-grid').innerHTML=profileItems(list)||'<p class="empty-state">No profiles match.</p>';document.querySelector('#profile-count').textContent=`${list.length} profiles`});document.querySelector('#compare-toggle').onclick=()=>{const el=document.querySelector('#profile-compare');el.hidden=!el.hidden}}
 if(['lookbook','rooms','home'].includes(view)){document.querySelectorAll('[data-story]').forEach(b=>b.addEventListener('click',()=>changeStory(Number(b.dataset.story))))}
 document.addEventListener('change',e=>{if(e.target.matches('[data-compare-finish]')){const key=e.target.dataset.compareFinish,[kind,n]=key.split(':');if(e.target.checked&&comparedFinishes.size>=4){e.target.checked=false;toast('Compare up to four finish references at a time.');return}e.target.checked?comparedFinishes.set(key,data[kind][Number(n)]):comparedFinishes.delete(key);renderFinishCompare();document.querySelector('#finish-compare').hidden=false}if(e.target.matches('[data-compare]')){const i=Number(e.target.dataset.compare);if(e.target.checked&&compared.size>=3){e.target.checked=false;toast('Compare up to three profiles at a time.');return}e.target.checked?compared.add(i):compared.delete(i);renderCompare();document.querySelector('#profile-compare').hidden=false}});
 document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.save){const key=b.dataset.save,[kind,n]=key.split(':'),r=data[kind][Number(n)];if(saved.some(x=>x.key===key)){saved=saved.filter(x=>x.key!==key);toast('Removed from your consultation brief.')}else{saved.push({key,kind,name:r.name,code:r.code||null,referencePage:r.printed_page||r.pdf_page||r.page});toast('Saved as an independent selection for review.')}persist()}if(b.dataset.detail)showDetail(b.dataset.detail);if(b.matches('.close-detail,[data-close-detail]'))document.querySelector('#detail-drawer')?.close();if(b.id==='saved-open'||b.id==='consult-saved'){const panel=document.querySelector('#saved-panel');panel.hidden=false;renderSaved();panel.querySelector('button')?.focus()}if(b.hasAttribute('data-close-saved'))document.querySelector('#saved-panel').hidden=true;if(b.dataset.uncompareFinish){comparedFinishes.delete(b.dataset.uncompareFinish);renderFinishCompare()}if(b.dataset.remove){saved=saved.filter(x=>x.key!==b.dataset.remove);persist()}if(b.id==='export-selections')download('asina-consultation-selections.json',{purpose:'Independent selections for project review',compatibility:'Confirm during project review',selections:saved});if(b.hasAttribute('data-tfl')){document.querySelector('#material-filter').value='Thermally Fused Laminate';finishLimit=finishPageSize;renderFinishes();document.querySelector('[data-material-family="Thermally Fused Laminate"]')?.focus()}if(b.dataset.room){const p=document.querySelector('[name=program]');if(p)p.value=b.dataset.room;toast(b.dataset.room+' added to your consultation direction.')}});
 if(view==='consultation'||view==='home')document.querySelector('#consult-form')?.addEventListener('submit',e=>{const form=e.currentTarget,error=document.querySelector('#form-error');if(isReleaseCandidate){if(!form.checkValidity()){e.preventDefault();error.textContent='Enter your name, a valid email and the project location / quantity.';form.querySelector(':invalid').focus();return}const selectionField=form.querySelector('[name="selection-summary"]');if(selectionField)selectionField.value=JSON.stringify(saved.map(({key,name,code})=>({key,name,code})));return}e.preventDefault();if(!form.checkValidity()){error.textContent='Enter your name, a valid email and the project location / quantity.';form.querySelector(':invalid').focus();return}error.textContent='';download('asina-project-review-draft.json',{status:'Local draft, not submitted or booked',project:Object.fromEntries(new FormData(form)),selections:saved,reviewNote:'Compatibility, dimensions, quote, schedule and shipping responsibility require project review.'});document.querySelector('#form-success').textContent='Consultation brief downloaded. No request has been sent.'});
 document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('#saved-panel').hidden=true});
}
function initInteractions(){renderFinishes();renderProducts();renderCompare();renderFinishCompare();document.querySelector('.menu-toggle').onclick=e=>{const open=e.currentTarget.getAttribute('aria-expanded')==='true';e.currentTarget.setAttribute('aria-expanded',!open);document.querySelector('.site-nav').classList.toggle('open',!open)};document.querySelector('.site-nav').addEventListener('click',e=>{if(e.target.closest('a')){document.querySelector('.site-nav').classList.remove('open');document.querySelector('.menu-toggle').setAttribute('aria-expanded','false')}});document.querySelector('#profile-search').addEventListener('input',e=>{const list=data.profiles.filter(r=>r.name.toLowerCase().includes(e.target.value.toLowerCase()));document.querySelector('#profile-grid').innerHTML=profileItems(list)||'<p class="empty-state">No profiles match. Try a different profile name.</p>';document.querySelector('#profile-count').textContent=`${list.length} profiles`});for(const sel of ['#material-filter','#finish-search','#tfl-type'])document.querySelector(sel).addEventListener(sel.includes('search')?'input':'change',()=>{finishLimit=finishPageSize;renderFinishes()});for(const sel of ['#product-category','#product-search'])document.querySelector(sel).addEventListener(sel.includes('search')?'input':'change',()=>{productLimit=productPageSize;renderProducts()});document.querySelector('#compare-toggle').onclick=()=>{const el=document.querySelector('#profile-compare');el.hidden=!el.hidden};document.querySelector('#finish-compare-toggle').onclick=()=>{const el=document.querySelector('#finish-compare');el.hidden=!el.hidden};document.querySelector('#finish-more').onclick=()=>{finishLimit+=24;renderFinishes()};document.querySelector('#product-more').onclick=()=>{productLimit+=16;renderProducts()};document.addEventListener('input',e=>{if(e.target.matches('.comparison-control input'))e.target.closest('#comparison-host').style.setProperty('--split',e.target.value+'%')});document.addEventListener('change',e=>{if(e.target.matches('[data-compare-finish]')){const key=e.target.dataset.compareFinish;const[kind,n]=key.split(':');if(e.target.checked&&comparedFinishes.size>=4){e.target.checked=false;toast('Compare up to four finish references at a time.');return}e.target.checked?comparedFinishes.set(key,data[kind][Number(n)]):comparedFinishes.delete(key);renderFinishCompare();document.querySelector('#finish-compare').hidden=false}if(e.target.matches('[data-compare]')){const i=Number(e.target.dataset.compare);if(e.target.checked&&compared.size>=3){e.target.checked=false;toast('Compare up to three profiles at a time.');return}e.target.checked?compared.add(i):compared.delete(i);renderCompare();document.querySelector('#profile-compare').hidden=false}});document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;if(b.dataset.save){const key=b.dataset.save;const[kind,n]=key.split(':'),r=data[kind][Number(n)];if(saved.some(x=>x.key===key)){saved=saved.filter(x=>x.key!==key);toast('Removed from your consultation brief.')}else{saved.push({key,kind,name:r.name,code:r.code||null,referencePage:r.printed_page||r.pdf_page||r.page});toast('Saved as an independent selection for review.')}persist()}if(b.dataset.story!==undefined)changeStory(Number(b.dataset.story));if(b.dataset.collection!==undefined)changeStory(Number(b.dataset.collection));if(b.dataset.detail)showDetail(b.dataset.detail);if(b.matches('.close-detail,[data-close-detail]'))document.querySelector('#detail-drawer').close();if(b.id==='saved-open'||b.id==='consult-saved'){const p=document.querySelector('#saved-panel');p.hidden=false;renderSaved();p.querySelector('button').focus()}if(b.hasAttribute('data-close-saved')){document.querySelector('#saved-panel').hidden=true;document.querySelector('#saved-open').focus()}if(b.dataset.uncompareFinish){comparedFinishes.delete(b.dataset.uncompareFinish);renderFinishCompare()}if(b.dataset.remove){saved=saved.filter(x=>x.key!==b.dataset.remove);persist()}if(b.id==='export-selections')download('asina-consultation-selections.json',{purpose:'Independent selections for project review',compatibility:'Confirm during project review',selections:saved});if(b.hasAttribute('data-tfl')){document.querySelector('#material-filter').value='Thermally Fused Laminate';finishLimit=finishPageSize;renderFinishes();document.querySelector('[data-material-family="Thermally Fused Laminate"]')?.focus()}if(b.dataset.room){document.querySelector('[name=program]').value=b.dataset.room;toast(b.dataset.room+' added to your consultation direction.')}});document.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelector('#saved-panel').hidden=true});document.querySelector('#consult-form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,error=document.querySelector('#form-error');if(!form.checkValidity()){error.textContent='Enter your name, a valid email and the project location / quantity.';form.querySelector(':invalid').focus();return}error.textContent='';download('asina-project-review-draft.json',{status:'Local draft, not submitted or booked',project:Object.fromEntries(new FormData(form)),selections:saved,reviewNote:'Compatibility, dimensions, quote, schedule and shipping responsibility require project review.'});document.querySelector('#form-success').textContent='Consultation brief downloaded. No request has been sent.'});const observer=new IntersectionObserver(entries=>{for(const en of entries)if(en.isIntersecting){document.querySelectorAll('[data-chapter]').forEach(a=>a.classList.toggle('active',a.dataset.chapter===en.target.id))}},{rootMargin:'-15% 0px -70% 0px'});document.querySelectorAll('section[id]').forEach(s=>observer.observe(s))}
function metadata(c){return `<dl class="design-spec">${[['Design thesis',c.thesis],['Aesthetic family',c.family],['Primary reference',c.primaryReference],['Secondary influences',c.secondaryReferences],['Type pairing',c.typePairing],['Main layout',c.layout],['Signature interaction',c.interaction],['Intentionally avoided',c.avoided],['Strengths',c.strengths],['Risks',c.risks],['Implementation complexity',c.complexity]].map(([a,b])=>`<div><dt>${a}</dt><dd>${esc(Array.isArray(b)?b.join(' · '):b)}</dd></div>`).join('')}<div><dt>Palette</dt><dd class="palette">${c.palette.map(p=>`<span><i style="background:${esc(p)}"></i>${esc(p)}</span>`).join('')}</dd></div>${c.dials?`<div><dt>Taste dials</dt><dd>${esc(typeof c.dials==='object'?JSON.stringify(c.dials):c.dials)}</dd></div>`:''}</dl>`}
function renderStage1Index(){const concepts=stage1Concepts;document.body.className='lab-index';app.innerHTML=`<header class="index-header"><a href="./">${image(data.logo,'Asina Global')}</a><span>DESIGN LAB / STAGE 01</span><a href="inspiration/manifest.md">Reference evidence ↗</a></header><main class="index-main"><div class="index-intro"><div><p class="eyebrow">Warm architectural precision</p><h1>One catalog.<br>Ten distinct directions.</h1></div><div><p>Explore each concept on desktop and mobile. The same catalog, sequence and consultation path make the differences in composition easier to assess.</p><p class="fine">Isolated local exploration · Choose a direction before Stage 2. No direction is preselected.</p><a href="#matrix" class="outline-btn">View comparison matrix ↓</a></div></div><div class="compare-toolbar"><span id="compare-selection">Select two or three concepts to view side by side.</span><button class="btn" id="launch-compare" disabled>Compare selected ↗</button></div>${[['I','Impeccable','Five narrative approaches, each with its own architectural rhythm.'],['T','Design Taste','Five layout systems, using the requested variance, motion and density settings.']].map(([prefix,label,copy])=>`<section class="concept-family"><div class="family-heading"><h2>${label}</h2><p>${copy}</p></div><div class="concept-index-grid">${concepts.filter(c=>c.id[0]===prefix).map(c=>`<article class="concept-card"><a class="concept-preview" href="?concept=${c.id}"><img src="screenshots/${c.id}-desktop.png" alt="${esc(c.name)} desktop screenshot" loading="lazy" onerror="this.hidden=true"><span>${c.id} / Open local preview ↗</span></a><div class="concept-card-body"><div class="concept-title"><span>${c.id}</span><h3><a href="?concept=${c.id}">${esc(c.name)}</a></h3><label><input type="checkbox" class="compare-concept" value="${c.id}"> Compare</label></div><p>${esc(c.thesis)}</p><div class="concept-links"><a href="?concept=${c.id}">Explore concept ↗</a><a href="screenshots/${c.id}-desktop-full.png">Full desktop</a><a href="screenshots/${c.id}-mobile-full.png">Full mobile</a></div><details><summary>Design dossier</summary>${metadata(c)}<div class="screenshot-pair"><a href="screenshots/${c.id}-desktop-full.png"><img src="screenshots/${c.id}-desktop.png" alt="Desktop ${c.id}" loading="lazy"></a><a href="screenshots/${c.id}-mobile-full.png"><img src="screenshots/${c.id}-mobile.png" alt="Mobile ${c.id}" loading="lazy"></a></div></details></div></article>`).join('')}</div></section>`).join('')}<section id="matrix" class="matrix-section"><h2>Comparison matrix</h2><p>Compare the tradeoffs. Choose any I-01–I-05 or T-01–T-05 to move into Editorial, Catalog and Balanced refinements.</p><div class="table-scroll"><table><thead><tr><th>Direction</th><th>Layout & emphasis</th><th>Strengths</th><th>Risks</th><th>Complexity</th></tr></thead><tbody>${concepts.map(c=>`<tr><th><a href="?concept=${c.id}">${c.id}<br>${esc(c.name)}</a></th><td>${esc(c.layout)}</td><td>${esc(c.strengths)}</td><td>${esc(c.risks)}</td><td>${esc(c.complexity)}</td></tr>`).join('')}</tbody></table></div></section><section class="lab-boundary"><h2>Ready for your direction.</h2><p>Stage 1 stops here. Select one concept to develop its Editorial, Catalog and Balanced variations. Image generation and the development tweaks bar follow approval in later stages.</p><p class="fine">All selections, comparisons and consultation drafts stay in this browser or download locally. Catalog suitability requires project review.</p></section></main><footer class="index-footer">Asina Global / Local design lab · <a href="README.md">Preview and source notes</a> · <a href="source-ledger.md">Source ledger</a></footer>`;const selected=new Set();document.querySelectorAll('.compare-concept').forEach(el=>el.onchange=()=>{if(el.checked&&selected.size>=3){el.checked=false;return}el.checked?selected.add(el.value):selected.delete(el.value);document.querySelector('#launch-compare').disabled=selected.size<2;document.querySelector('#compare-selection').textContent=selected.size?[...selected].join(' / '):'Select two or three concepts to view side by side.'});document.querySelector('#launch-compare').onclick=()=>{location.href='?compare='+[...selected].join(',')}}
function renderConcept(c){
 isSelectedPreview=c.id==='I-03-C';
 const requestedView=params.get('view')||'home',guideId=params.get('page')||'',draftMode=params.has('draft');
 const articleLayout=['1','2','3','4','5'].includes(params.get('article-layout'))?params.get('article-layout'):'4';
 const editorialVariant=['1','2','3','4','5'].includes(params.get('editorial-variant'))?params.get('editorial-variant'):'5';
 const matchedGuide=seoPages.find(page=>page.id===guideId||page.aliases?.includes(guideId));
 const selectedGuide=matchedGuide?{...matchedGuide,openArticleId:params.get('topic')||(matchedGuide.id!==guideId?guideId:null)}:null;
 const view=isSelectedPreview?((requestedView==='guide'&&!selectedGuide)?'guides':(['guide','guides'].includes(requestedView)?requestedView:requestedView==='lookbook'?'rooms':requestedView)):'home';
 const materialLayout=['1','2','3','4','5'].includes(params.get('layout'))?params.get('layout'):'4';
 const priceVariant=['1','2','3','4','5'].includes(params.get('price'))?params.get('price'):'5';
 suppressSectionNumbers=isSelectedPreview;
 if(isSelectedPreview&&selectedMedia.rooms)data={...data,programImages:selectedMedia.rooms,collectionImages:selectedMedia.rooms.collections,profiles:data.profiles.map((r,i)=>({...r,...selectedMedia.profiles[i]})),products:data.products.map((r,i)=>({...r,...selectedMedia.products[i]}))};
 updateLocalViewMetadata(view,selectedGuide);
 document.body.className=`concept-page ${c.bodyClass||c.id.toLowerCase().replace('-','')}${view==='materials'?' mat-layout-'+materialLayout+(materialLayout==='4'?' price-variant-'+priceVariant:''):''}${draftMode?' draft-preview':''}${params.has('embed')?' embed':''}`;
 const style=document.createElement('style');style.textContent=c.css+(c.id==='I-03-C'?seoLibraryCSS+(view==='home'?homeMotionCSS:''):'');document.head.append(style);
 const homeHero=view==='home'?(c.id==='I-03-C'?c.hero(data).replace('class="hero-image"',`class="hero-image" ${dimensions(data.hero_image)} loading="eager" fetchpriority="high"`):c.hero(data)):'';
 const noCatalogHeader=['guide','guides','about'].includes(view);
 const body=view==='guides'?renderGuideIndex(esc):view==='guide'?renderGuidePage(selectedGuide,esc,image,articleLayout,editorialVariant):view==='about'?renderWhoWeAre(esc,image):view==='home'?`${program()}${collectionsSection()}${homeConstruction()}${homeDecisionSequence()}<section class="section home-process-summary"><div class="section-heading"><h2>Our process, through customization.</h2><p class="section-intro">A clear path from room plans to a reviewed, project-specific specification.</p></div><div class="home-summary-grid"><ol class="process-list"><li><span>01</span><div><h3>Share the project</h3><p>Send room plans or cabinet runs, quantities, destination and timing.</p></div></li><li><span>02</span><div><h3>Set the direction</h3><p>Choose room style, door profile, finish, Quick Book references, accessories and countertop direction.</p></div></li><li><span>03</span><div><h3>Review and customize</h3><p>Discuss custom colors, profiles or sizing. Technical feasibility, samples and project details are confirmed before approval.</p></div></li><li><span>04</span><div><h3>Coordinate production</h3><p>Approved specifications guide production review, QA, packing and project-specific shipping planning.</p></div></li></ol><a class="text-link" href="?concept=I-03-C&view=consultation">Start a project review ↗</a></div></section>${consultation()}`:view==='lookbook'?`${lookbookSection()}${transformation()}${completeRoom()}`:view==='technical'?`${construction()}${technicalSpecsSection()}`:view==='profiles'?profiles():view==='materials'?materialPage(materialLayout,priceVariant):view==='configurations'?`${configurations()}${quickBookReader()}`:view==='quickbook'?quickBookReader():view==='accessories-catalogue'?accessoriesCatalogueReader():view==='accessories'?accessories():view==='countertops'?countertopsPage({section,image,data,esc}):view==='rooms'?`${lookbookSection()}${transformation()}${completeRoom()}`:view==='faqs'?faqPage():view==='consultation'?consultation():`${program()}${collectionsSection()}${consultation()}`;
 app.innerHTML=`<a class="skip-link" href="#main-content">Skip to main content</a><div id="top"></div>${conceptHeader(c,draftMode)}<main id="main-content">${homeHero}${noCatalogHeader?'':catalogPageHeader(view)}${chapterNav(view)}${body}${view==='materials'?quickBookReference():''}${['home','about'].includes(view)?'':nextStage(view)}</main><footer class="site-footer"><a class="brand" href="#top">${image(data.logo,'Asina Global')}</a><p>Cabinetry. Countertops. Custom furniture packages.</p>${draftMode?'':`<a href="${c.stage===2?'?stage=2':'?stage=1'}">Return to ${c.stage===2?'refinement':'concept'} comparison ↗</a><small>Stage ${c.stage||1} · Local design exploration · Subject to approved specifications</small>`}</footer><aside class="saved-panel" id="saved-panel" aria-labelledby="saved-title" hidden></aside><dialog class="detail-drawer" id="detail-drawer"></dialog><div class="toast" role="status" aria-live="polite"></div>`;
 normalizePublicLinks(app);
 if(draftMode&&!isReleaseCandidate)app.querySelectorAll('a[href^="?concept=I-03-C"]').forEach(link=>{const url=new URL(link.getAttribute('href'),location.href);url.searchParams.set('draft','1');link.setAttribute('href',url.pathname+url.search+url.hash)});
 finishPageSize=c.initialFinishLimit||12;productPageSize=c.initialProductLimit||8;finishLimit=isReleaseCandidate?data.finishes.length:finishPageSize;productLimit=productPageSize;
 if(isSelectedPreview)initSelectedPageInteractions(view);else initInteractions();
 if(view==='home')initHomeScrollMotion();
 if(isSelectedPreview&&view==='guides')attachGuideSearch();
 if(isSelectedPreview&&['lookbook','rooms','home'].includes(view))initImageComparison();
 c.init?.(data);
 applyResponsiveImages(app);
 if(c.id==='I-03-C'&&localLabMarker==='local-preview'&&['127.0.0.1','localhost','[::1]'].includes(location.hostname)&&!draftMode&&!params.has('embed')&&!params.has('review')){const css=document.createElement('link');css.rel='stylesheet';css.href='stage4/tweaks.css';document.head.append(css);import('./stage4/tweaks.js').then(m=>m.mountTweaks({serverMarker:localLabMarker,conceptId:c.id})).catch(e=>console.error('Local design controls could not load',e))}
}

function renderSideBySide(){const list=(params.get('compare')||'').split(',').filter(id=>concepts.some(c=>c.id===id)).slice(0,3);document.body.className='lab-compare'+(list.every(id=>id.startsWith('I-03-'))?' refinement-compare':'');document.title='Asina Global / Side-by-side refinements';app.innerHTML=`<header class="compare-header"><a href="./">← Comparison index</a><span>${list.join(' / ')} · Independent scroll</span><label>Viewport <select id="compare-viewport"><option value="desktop">Desktop</option><option value="mobile">Mobile</option></select></label></header><main class="side-by-side">${list.map(id=>`<section><h1><a href="?concept=${id}">${id} / ${esc(concepts.find(c=>c.id===id).name)} ↗</a></h1><div class="frame-wrap"><iframe src="?concept=${id}&embed=1" title="${id} local concept" loading="eager"></iframe></div></section>`).join('')}</main>`;const fitFrames=()=>document.querySelectorAll('.frame-wrap').forEach(w=>{const f=w.querySelector('iframe'),mobile=document.body.classList.contains('compare-mobile'),scale=mobile?1:w.clientWidth/1440;f.style.width=mobile?'390px':'1440px';f.style.height=(w.clientHeight/scale)+'px';f.style.transform=`scale(${scale})`;f.style.transformOrigin='top left'});document.querySelector('#compare-viewport').onchange=e=>{document.body.classList.toggle('compare-mobile',e.target.value==='mobile');fitFrames()};const resize=new ResizeObserver(fitFrames);document.querySelectorAll('.frame-wrap').forEach(w=>resize.observe(w));fitFrames()}
function renderStage2Index(){
 document.body.className='lab-index stage2-index';document.title='I-03 / Three refinements | Asina Global';
 app.innerHTML=`<header class="index-header"><a href="./">${image(data.logo,'Asina Global')}</a><span>DESIGN LAB / STAGE 02</span><a href="?stage=1">Stage 1 archive ↗</a></header><main class="index-main"><div class="index-intro"><div><p class="eyebrow">Selected direction / I-03</p><h1>The publication.<br>Three ways to read it.</h1></div><div><p>I-03, Catalog-to-Web Editorial, is the selected visual language. Compare three refinements of its reading rhythm, chapter layout and catalog density.</p><p class="fine">All three preserve the Barlow Condensed / Manrope pairing, warm palette, source imagery, catalog facts and consultation path.</p><a class="btn" href="?compare=I-03-A,I-03-B,I-03-C">Compare all three live ↗</a></div></div><div class="refinement-shared"><span>Same identity. Same catalog. Same order.</span><div><a href="?concept=I-03">View original I-03 ↗</a><a href="stage2/comparison.md">Comparison notes ↗</a></div></div><section aria-label="Three I-03 refinements" class="refinement-index-grid">${refinements.map(c=>`<article class="concept-card refinement-card"><div class="variation-name"><span>VARIATION ${c.variation}${c.id==='I-03-C'?' / SELECTED':''}</span><h2>${c.name}</h2></div><a class="concept-preview" href="?concept=${c.id}"><img src="stage2/screenshots/${c.id}-desktop.png" alt="${esc(c.name)} refinement, desktop" loading="lazy"><span>${c.id} / Open full preview ↗</span></a><div class="concept-card-body"><p>${esc(c.thesis)}</p><div class="concept-links"><a href="?concept=${c.id}">Explore ${c.name} ↗</a><a href="stage2/screenshots/${c.id}-desktop-full.png">Full desktop</a><a href="stage2/screenshots/${c.id}-mobile-full.png">Full mobile</a></div><dl class="refinement-traits"><div><dt>Reading rhythm</dt><dd>${c.variation==='A'?'Slow, image-led spreads':c.variation==='B'?'Fast, indexed browsing':'Room context, then specification'}</dd></div><div><dt>Catalog preview</dt><dd>${c.initialFinishLimit} finishes / ${c.initialProductLimit} configurations initially visible; the complete libraries remain accessible.</dd></div><div><dt>Navigation</dt><dd>${c.variation==='A'?'Static chapter index':c.variation==='B'?'Sticky chapters + specification shortcuts':'Sticky chapters + wider comparison plates'}</dd></div></dl><details><summary>Refinement dossier</summary>${metadata(c)}<div class="screenshot-pair"><a href="stage2/screenshots/${c.id}-desktop-full.png"><img src="stage2/screenshots/${c.id}-desktop.png" alt="${c.name}, desktop" loading="lazy"></a><a href="stage2/screenshots/${c.id}-mobile-full.png"><img src="stage2/screenshots/${c.id}-mobile.png" alt="${c.name}, mobile" loading="lazy"></a></div></details></div></article>`).join('')}</section><section class="matrix-section"><h2>What changes between the three?</h2><div class="table-scroll"><table><thead><tr><th>Refinement</th><th>Main layout</th><th>Strengths</th><th>Tradeoff</th></tr></thead><tbody>${refinements.map(c=>`<tr><th><a href="?concept=${c.id}">${c.variation} / ${c.name}</a></th><td>${esc(c.layout)}</td><td>${esc(c.strengths)}</td><td>${esc(c.risks)}</td></tr>`).join('')}</tbody></table></div></section><section class="lab-boundary"><h2>Choose the reading rhythm.</h2><div><p>You selected C / Balanced. Its local preview now includes presentation controls.</p><p class="fine">These remain local concepts. The asset audit reuses local catalog imagery; design controls are available only in the selected local preview. All saved product references remain independent consultation candidates.</p></div></section></main><footer class="index-footer">Asina Global / I-03 refinements · <a href="stage2/README.md">Stage 2 notes</a> · <a href="inspiration/manifest.md">Reference evidence</a></footer>`;
}
try{const [response,mediaResponse,polishResponse,contentResponse,responsiveResponse]=await Promise.all([fetch('/data.json'),fetch('/approved/media.json'),fetch('/section-polish/media-overrides.json'),fetch('/bundle-content.json'),fetch('/responsive-image-manifest.json')]);if(polishResponse.ok)selectedMedia=await polishResponse.json();if(mediaResponse.ok)imageMetadata=await mediaResponse.json();if(contentResponse.ok)siteContent=await contentResponse.json();if(responsiveResponse.ok)responsiveImages=await responsiveResponse.json();if(!response.ok)throw Error('Product references could not be loaded.');localLabMarker=response.headers.get('X-Asina-Design-Lab')||'';data=await response.json();if(params.has('notes')){const c=concepts.find(c=>c.id===params.get('notes'));if(!c)throw Error('Unknown concept identifier.');document.body.className='lab-index';app.innerHTML=`<main class="notes-page"><a href="./">← All concepts</a><h1>${c.id} / ${esc(c.name)}</h1>${metadata(c)}<a class="btn" href="?concept=${c.id}">Open concept ↗</a></main>`}else if(params.has('compare'))renderSideBySide();else if(id){const c=concepts.find(c=>c.id===id);if(!c)throw Error('Unknown concept. Return to the comparison index.');renderConcept(c)}else if(params.get('stage')==='1')renderStage1Index();else if(params.get('stage')==='2')renderStage2Index();else renderConcept(concepts.find(c=>c.id==='I-03-C'))}catch(e){app.innerHTML=`<main class="notes-page"><h1>The preview could not load.</h1><p>${esc(e.message)}</p><a href="./">Return to comparison index</a></main>`;console.error(e)}
if(isReleaseCandidate){const form=document.querySelector('#consult-form');if(form){form.addEventListener('submit',event=>{event.stopImmediatePropagation();const summary=form.querySelector('[name="selection-summary"]');if(summary)summary.value=saved.map(item=>[item.name,item.code].filter(Boolean).join(' · ')).join('; ');HTMLFormElement.prototype.submit.call(form)},true)}}
